edits:
    {% if 'X' not in params and  'Y' not in params  %}
        SET_KINEMATIC_POSITION X=100
        SET_KINEMATIC_POSITION Y=100
        SET_KINEMATIC_POSITION Z={printer.toolhead.axis_maximum.z/2}
        G91
        G1 Z5 F600
#        G1 X-5 F2400
#        G1 Y2 F2400
        G4 P2000
        _HOME_XY
        G90
    {% if 'X' not in params and  'Y' not in params  %}
        # q2-start-keep-xy: only for the first homing of a print (PRINT_START sends TWEAKED_KEEP_XY): homed X and Y are not
        # homed again, only Z, when the plate check of this start has just homed them (the mark counts once) or when
        # TWEAKED_START_XY MODE=ANY was chosen.
        {% set q2_trusted = printer['gcode_macro _TWEAKED_START_HOME'].xy_fresh|int == 1 or printer.save_variables.variables.q2_start_keep_any|default(0)|int == 1 %}
        {% set q2_keep_xy = 'TWEAKED_KEEP_XY' in params and q2_trusted and 'x' in printer.toolhead.homed_axes and 'y' in printer.toolhead.homed_axes %}
        {% if 'TWEAKED_KEEP_XY' in params %}
        SET_GCODE_VARIABLE MACRO=_TWEAKED_START_HOME VARIABLE=xy_fresh VALUE=0
        {% endif %}
        {% if not q2_keep_xy %}
        SET_KINEMATIC_POSITION X=100
        SET_KINEMATIC_POSITION Y=100
        {% endif %}
        SET_KINEMATIC_POSITION Z={printer.toolhead.axis_maximum.z/2}
        G91
        G1 Z5 F600
#        G1 X-5 F2400
#        G1 Y2 F2400
        G4 P2000
        {% if not q2_keep_xy %}
        _HOME_XY
        {% endif %}
        G90
    SET_PRINT_SUB_STATUS SUB_STATUS=tool_head_reset
    G28   
    SET_PRINT_SUB_STATUS SUB_STATUS=tool_head_reset
    G28 TWEAKED_KEEP_XY  # q2-start-keep-xy: X and Y just homed by the plate check are not homed again
[homing_override]
# q2-start-keep-xy: xy_fresh is 1 only between a plate check that has just homed X and Y and the first homing of
# PRINT_START.
[gcode_macro _TWEAKED_START_HOME]
variable_xy_fresh: 0
gcode:
    M118 The plate check sets this mark; the first homing of a print start reads it.

[gcode_macro TWEAKED_START_XY]
description: Print start: keep homed X and Y only after the plate check (MODE=CHECK) or after any homing (MODE=ANY)
gcode:
    {% set mode = params.MODE|default('')|upper %}
    {% if mode == 'CHECK' %}
        SAVE_VARIABLE VARIABLE=q2_start_keep_any VALUE=0
    {% elif mode == 'ANY' %}
        SAVE_VARIABLE VARIABLE=q2_start_keep_any VALUE=1
    {% elif mode %}
        { action_raise_error("TWEAKED_START_XY: use MODE=CHECK or MODE=ANY") }
    {% endif %}
    {% set now = mode if mode else ('ANY' if printer.save_variables.variables.q2_start_keep_any|default(0)|int == 1 else 'CHECK') %}
    M118 Print start keeps homed X and Y: MODE={now}

[homing_override]
